#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=6
SOURCE_COMMIT="9ab99c7"
PROJECT_ID="appgprj_6a9d4f5aac64819193587b0f41052c06"

banner "Firstleaf · Sites private deploy (step 7)"

stage "ADMIN_EMAIL in Sites settings"
say "Owner bootstrap uses ADMIN_EMAIL against the ChatGPT sign-in email (case-insensitive)."
note "Project id: $PROJECT_ID · source commit to deploy: $SOURCE_COMMIT"
open_url "https://chatgpt.com/sites"
step "Find this Firstleaf Site (linked by .openai/hosting.json project_id)."
step "Open More actions → Settings → hosted environment variables / secrets."
step "Add or update ADMIN_EMAIL = the email you use to sign in with ChatGPT."
ask ADMIN_EMAIL "Paste the ADMIN_EMAIL you set in Sites:"
[[ -n "$ADMIN_EMAIL" ]] || { warn "ADMIN_EMAIL is required"; exit 1; }
write_env ADMIN_EMAIL "$ADMIN_EMAIL"
note "Keep this value out of git commits and chat prompts when possible."
pause "Press Enter after ADMIN_EMAIL is saved in Sites settings."

stage "Optional SITE_ORIGIN"
say "SITE_ORIGIN must match the live site origin for same-origin write checks."
note "You can set it after Deploy once you know the production URL, then redeploy."
ask SITE_ORIGIN "Paste SITE_ORIGIN now (or leave blank to set after deploy):"
if [[ -n "$SITE_ORIGIN" ]]; then
  write_env SITE_ORIGIN "$SITE_ORIGIN"
  step "In Sites settings, add SITE_ORIGIN to the same value (no trailing slash)."
  pause "Press Enter after SITE_ORIGIN is saved (or skipped for now)."
else
  note "Skipped for now — stage 5 will ask again after you have the URL."
fi

stage "Private / owner-only access"
say "This pilot must stay private: owner-only until you deliberately widen Sites access."
open_url "https://chatgpt.com/sites"
step "In Site settings / sharing, confirm access is private or owner-only."
step "Do not invite real clients yet; test records only."
confirm "Access is private / owner-only right now?" || warn "Fix access before deploying to an audience."
pause "Press Enter to continue."

stage "Save a version (build candidate)"
say "Save a version without making it live yet. Sites should associate the build with git commit $SOURCE_COMMIT."
open_url "https://chatgpt.com/sites"
step "In ChatGPT Sites (or ask ChatGPT): save a version for this local project."
step "Suggested prompt: Save a Sites version for Firstleaf at commit $SOURCE_COMMIT. Do not deploy yet. Confirm the commit and that D1/R2 bindings and drizzle migrations are included."
step "Wait until the version build succeeds and note any migration review notes."
pause "Press Enter after the saved version build succeeded."

stage "Deploy the saved version"
say "Deploy publishes production. Only do this when you want the private audience to reach the site."
confirm "Deploy the saved version now?" || { warn "Stopped before deploy. Re-run this wizard when ready."; finish; exit 0; }
open_url "https://chatgpt.com/sites"
step "Deploy the approved saved version."
step "Suggested prompt: Deploy the approved Firstleaf Sites version for commit $SOURCE_COMMIT and give me the production URL."
ask SITE_URL "Paste the production site URL (https://...):"
[[ -n "$SITE_URL" ]] || { warn "Production URL is required for handoff"; exit 1; }
write_env SITE_URL "$SITE_URL"
if [[ -z "${SITE_ORIGIN:-}" ]]; then
  # Derive origin from URL if SITE_ORIGIN was deferred.
  SITE_ORIGIN=$(printf '%s' "$SITE_URL" | sed -E 's#(https?://[^/]+).*#\1#')
  write_env SITE_ORIGIN "$SITE_ORIGIN"
  step "Add SITE_ORIGIN=$SITE_ORIGIN in Sites settings, then ask ChatGPT to redeploy the same version so writes use the correct origin."
  pause "Press Enter after SITE_ORIGIN is set (and redeployed if required)."
fi

stage "Handoff check on /portal"
say "Verify the owner lands as an approved admin and the portal UI loads."
open_url "${SITE_URL%/}/portal"
step "Sign in with ChatGPT using the ADMIN_EMAIL account."
step "Confirm /portal shows the workspace (not only the sign-in card)."
step "Confirm your role is admin / approved (overview loads without pending notice)."
step "Optional: Site tools should expose firstleaf_get_profile and firstleaf_get_overview when supported."
confirm "Portal handoff checks passed?" || warn "Fix login/admin bootstrap before marking step 7 complete."
ask HANDOFF_NOTES "Any handoff notes to store in .env (or leave blank):"
[[ -n "$HANDOFF_NOTES" ]] && write_env HANDOFF_NOTES "$HANDOFF_NOTES"
write_env DEPLOY_COMMIT "$SOURCE_COMMIT"
note "When checks pass, mark docs/implementation.md step 7 [x] and record SITE_URL in your handoff."

finish
note "Source commit: $SOURCE_COMMIT"
note "If portal works, tell the agent: step 7 succeeded with URL <SITE_URL>"
